/* SUSUN PERMINTAAN — sempit dan spesifik.
 *
 * Model diberi TIGA hal saja: kode aslinya, daftar baris yang ditolak
 * mesin Pine kita, dan aturan mainnya. Tidak diberi kebebasan menulis
 * ulang skrip dari nol — indikator yang "diperbaiki" jadi indikator lain
 * adalah kerusakan yang paling sulit disadari pemiliknya. */
const b = $input.first().json.body ?? $input.first().json;
const kode = String(b.kode || '');
const galat = Array.isArray(b.galat) ? b.galat : [];
const dilewati = Array.isArray(b.dilewati) ? b.dilewati : [];

const aturan = [
  'Kamu memperbaiki skrip Pine v5/v6 agar bisa dijalankan mesin Pine sederhana milik Jadi Trader Tools.',
  'ATURAN YANG TIDAK BOLEH DILANGGAR:',
  '1. Perbaiki HANYA baris yang bermasalah. Jangan menulis ulang skrip, jangan merapikan gaya, jangan mengganti nama variabel yang sudah jalan.',
  '2. JANGAN mengubah maksud indikatornya. Kalau sebuah baris tidak bisa didukung, komentari baris itu dan jelaskan — jangan menggantinya dengan perhitungan lain yang kelihatan mirip.',
  '3. Pertahankan deklarasi indicator()/study() apa adanya, termasuk overlay=.',
  '4. Balas HANYA JSON valid, tanpa pagar kode markdown, dengan bentuk:',
  '   {"kode":"<skrip lengkap hasil perbaikan>","penjelasan":"<2-4 kalimat>","perubahan":["baris X: ..."]}',
].join('\n');

const permintaan = [
  '## Baris yang DITOLAK mesin',
  galat.length ? galat.map((g, i) => `${i + 1}. ${g}`).join('\n') : '(tidak ada)',
  '',
  '## Baris yang DILEWATI (belum didukung)',
  dilewati.length ? dilewati.map((g, i) => `${i + 1}. ${g}`).join('\n') : '(tidak ada)',
  '',
  b.catatan ? `## Catatan pengguna\n${b.catatan}\n` : '',
  '## Skrip lengkap',
  kode,
].join('\n');

return [{ json: { aturan, permintaan, kodeAsli: kode, jumlahGalat: galat.length + dilewati.length } }];

/* URAI JAWABAN — dan jangan percaya begitu saja.
 *
 * Model kadang membungkus JSON-nya dengan pagar markdown atau menambah
 * kalimat pengantar. Dua hal diperiksa sebelum jawabannya diteruskan:
 * bentuknya JSON yang sah, dan kodenya tidak menyusut drastis. Skrip 400
 * baris yang kembali jadi 30 baris bukan perbaikan, itu kehilangan. */
const raw = $input.first().json;
const asli = $('Susun permintaan').first().json.kodeAsli || '';

let teks = raw.content ?? raw.text ?? raw.message?.content ?? raw.output ?? '';
if (Array.isArray(teks)) teks = teks.map(x => x.text ?? x).join('');
teks = String(teks).trim();

/* Buang pagar markdown kalau ada. */
teks = teks.replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();

let j;
try {
  j = JSON.parse(teks);
} catch (e) {
  /* Coba ambil objek JSON pertama yang utuh di dalam teks. */
  const m = teks.match(/\{[\s\S]*\}/);
  if (!m) return [{ json: { error: 'Jawaban agen bukan JSON yang bisa dibaca.' } }];
  try { j = JSON.parse(m[0]); }
  catch (e2) { return [{ json: { error: 'Jawaban agen bukan JSON yang bisa dibaca.' } }]; }
}

const kode = String(j.kode || '');
if (kode.length < 10) return [{ json: { error: 'Agen tidak mengembalikan kode.' } }];
if (asli && kode.length < asli.length * 0.5) {
  return [{ json: { error: `Perbaikan ditolak: kodenya menyusut dari ${asli.length} ke ${kode.length} karakter. Itu penulisan ulang, bukan perbaikan.` } }];
}

return [{ json: {
  kode,
  penjelasan: String(j.penjelasan || ''),
  perubahan: Array.isArray(j.perubahan) ? j.perubahan.map(String) : [],
} }];
